"""Validated configuration. New installs never energize an unknown relay."""
import json

VERSION = '4.0.2'

def defaults():
    channel = lambda i: dict(id=i, name='Pflanze %d' % (i + 1), enabled=True,
        sensor_pin=34+i, pump_pin=27-i, active_low=False, hardware_confirmed=False,
        dry_adc=None, wet_adc=None, flow_ml_s=None, auto=False, threshold=35,
        hysteresis=5, portion_ml=10, soak_seconds=300, max_cycle_ml=50,
        max_day_ml=200, max_run_seconds=30, min_rise=2, profile='custom')
    return dict(schema=4, board='esp32', name='Smart Irrigation', setup_done=False,
        wifi=dict(ssid='', password='', ap_password=''),
        mqtt=dict(enabled=False, host='', port=1883, username='', password='',
                  topic='smart_irrigation_v4', interval=60),
        tank=dict(trigger_pin=18, echo_pin=19, full_cm=None, empty_cm=None,
                  stop_cm=None, resume_cm=None, points=[], percent_points=[]),
        safety=dict(boot_pause_seconds=60, max_total_day_ml=400),
        channels=[channel(0), channel(1)])

def number(value, low, high, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not low <= value <= high:
        raise ValueError(label + ': ungueltiger Wert')
    return value

def validate(cfg):
    if not isinstance(cfg, dict) or cfg.get('schema') != 4:
        raise ValueError('Konfiguration muss Schema 4 haben')
    if cfg.get('board') not in ('unknown', 'esp32', 'esp32s3'):
        raise ValueError('Unbekannter Boardtyp')
    if not isinstance(cfg.get('name'), str) or not 1 <= len(cfg['name']) <= 48:
        raise ValueError('Name: 1 bis 48 Zeichen')
    outputs = set([13,14,16,17,18,19,21,22,23,25,26,27,32,33]) if cfg['board'] == 'esp32' else set(list(range(4,19)) + [21,38,39,40,41,42])
    inputs = set([32,33,34,35,36,39]) if cfg['board'] == 'esp32' else set(range(4,11))
    used = set()
    def pin(p, allowed):
        if p is None:
            return
        if cfg['board'] == 'unknown' or type(p) is not int or p not in allowed or p in used:
            raise ValueError('GPIO unzulaessig oder doppelt: ' + str(p))
        used.add(p)
    chs = cfg.get('channels', [])
    if not isinstance(chs, list) or not 1 <= len(chs) <= 4:
        raise ValueError('1 bis 4 Kanaele erforderlich')
    ids = set()
    for ch in chs:
        cid = ch.get('id')
        if type(cid) is not int or not 0 <= cid <= 3 or cid in ids:
            raise ValueError('Kanal-ID muss eindeutig sein (0..3)')
        ids.add(cid)
        if not isinstance(ch.get('name'), str) or not 1 <= len(ch['name']) <= 48:
            raise ValueError('Kanalname: 1 bis 48 Zeichen')
        for key in ('enabled', 'auto', 'hardware_confirmed'):
            if type(ch.get(key)) is not bool:
                raise ValueError(key + ': bool erforderlich')
        if ch.get('active_low') is not None and type(ch['active_low']) is not bool:
            raise ValueError('Relaislogik fehlt')
        pin(ch.get('pump_pin'), outputs)
        pin(ch.get('sensor_pin'), inputs)
        for key in ('dry_adc', 'wet_adc'):
            if ch.get(key) is not None:
                number(ch[key], 10, 4085, key)
        if ch.get('flow_ml_s') is not None:
            number(ch['flow_ml_s'], 0.1, 1000, 'Foerdermenge')
        for key, lo, hi in [('threshold',1,95),('hysteresis',1,20),('portion_ml',1,1000),
                            ('soak_seconds',30,86400),('max_cycle_ml',1,5000),
                            ('max_day_ml',1,50000),('max_run_seconds',1,60),('min_rise',1,20)]:
            number(ch.get(key), lo, hi, key)
        if ch['threshold'] + ch['hysteresis'] > 100:
            raise ValueError('Feuchteziel ueber 100%')
        if not ch['portion_ml'] <= ch['max_cycle_ml'] <= ch['max_day_ml']:
            raise ValueError('Portion <= Zykluslimit <= Tageslimit erforderlich')
        if ch['hardware_confirmed'] and (ch.get('active_low') is None or ch.get('pump_pin') is None or ch.get('sensor_pin') is None):
            raise ValueError('Hardware noch unvollstaendig')
        if ch['auto'] and not ready_channel(ch):
            raise ValueError('Kanal zuerst vollstaendig kalibrieren')
    tank = cfg['tank']
    pin(tank.get('trigger_pin'), outputs)
    pin(tank.get('echo_pin'), outputs | inputs)
    keys = ['full_cm','empty_cm','stop_cm','resume_cm']
    for key in keys:
        if tank.get(key) is not None:
            number(tank[key], 2, 350, key)
    if all(tank.get(k) is not None for k in keys):
        if not tank['full_cm'] < tank['resume_cm'] < tank['stop_cm'] <= tank['empty_cm']:
            raise ValueError('Tank: voll < Freigabe < Reserve <= leer (Abstaende)')
    pts = tank.get('points', [])
    if not isinstance(pts, list) or len(pts) > 12:
        raise ValueError('Maximal 12 Tank-Kalibrierpunkte')
    prev = None
    for p in pts:
        if not isinstance(p, list) or len(p) != 2:
            raise ValueError('Tankpunkte: [Abstand_cm, Liter]')
        number(p[0], 2, 350, 'Tankabstand'); number(p[1], 0, 1000, 'Liter')
        if prev and (p[0] <= prev[0] or p[1] >= prev[1]):
            raise ValueError('Tankpunkte: Abstand steigend, Liter fallend')
        prev = p
    percent = tank.get('percent_points', [])
    if not isinstance(percent, list) or len(percent) not in (0, 3):
        raise ValueError('Tank: drei Prozent-Kalibrierpunkte erforderlich')
    for i, p in enumerate(percent):
        if not isinstance(p, list) or len(p) != 2:
            raise ValueError('Tank-Prozentpunkte: [Abstand_cm, Prozent]')
        number(p[0], 2, 350, 'Tankabstand'); number(p[1], 0, 100, 'Tankprozent')
        if p[1] != (100, 50, 0)[i] or (i and p[0] <= percent[i-1][0]):
            raise ValueError('Tankpunkte: voll 100%, halbvoll 50%, leer 0%; Abstand steigend')
    if percent and (percent[0][0] != tank.get('full_cm') or percent[2][0] != tank.get('empty_cm')):
        raise ValueError('Tank-Prozentpunkte passen nicht zu voll/leer')
    number(cfg['safety']['boot_pause_seconds'],30,3600,'Startpause')
    number(cfg['safety']['max_total_day_ml'],1,100000,'Gesamtlimit')
    for k in ('ssid','password','ap_password'):
        if not isinstance(cfg['wifi'].get(k), str) or len(cfg['wifi'][k]) > 64:
            raise ValueError('WLAN-Einstellung ungueltig')
    if cfg['wifi']['ap_password'] and len(cfg['wifi']['ap_password']) < 8:
        raise ValueError('Setup-WLAN-Passwort: mindestens 8 Zeichen')
    mq = cfg['mqtt']
    if type(mq.get('enabled')) is not bool:
        raise ValueError('MQTT enabled: bool erforderlich')
    for k in ('host','username','password','topic'):
        if not isinstance(mq.get(k), str) or len(mq[k]) > 128:
            raise ValueError('MQTT-Einstellung ungueltig')
    if not mq['topic'] or any(c in mq['topic'] for c in ('+','#','\x00',' ')):
        raise ValueError('MQTT-Topic ungueltig')
    if type(mq['port']) is not int: raise ValueError('MQTT-Port muss ganzzahlig sein')
    if mq['enabled'] and not mq['host']: raise ValueError('MQTT-Broker fehlt')
    number(mq['port'],1,65535,'MQTT-Port'); number(mq['interval'],5,3600,'MQTT-Intervall')
    return cfg

def ready_channel(ch):
    return (ch.get('hardware_confirmed') and ch.get('dry_adc') is not None and
            ch.get('wet_adc') is not None and abs(ch['dry_adc']-ch['wet_adc']) >= 100 and
            ch.get('flow_ml_s') is not None)

def ready_tank(t):
    return (t.get('trigger_pin') is not None and t.get('echo_pin') is not None and
            all(t.get(k) is not None for k in ('full_cm','empty_cm','stop_cm','resume_cm')))

def clone(obj):
    return json.loads(json.dumps(obj))

"""Two verified slots; a truncated or interrupted write preserves the last generation."""
import json
try:
    import hashlib
except ImportError:
    import uhashlib as hashlib
try:
    import binascii
except ImportError:
    import ubinascii as binascii


def digest(data):
    return binascii.hexlify(hashlib.sha256(data).digest()).decode()

class Store:
    def __init__(self, prefix):
        self.prefix = prefix
        self.sequence = 0

    def load(self, default=None, strict=False):
        found = []
        exists = False
        for suffix in ('.a', '.b'):
            try:
                with open(self.prefix + suffix) as f:
                    raw = f.read()
                exists = True
                item = json.loads(raw)
                payload = item['payload']
                if item['hash'] == digest(payload.encode()):
                    found.append((item['sequence'], json.loads(payload)))
            except OSError:
                pass
            except Exception:
                exists = True
        if found:
            found.sort(key=lambda x: x[0])
            self.sequence, value = found[-1]
            return value
        if strict and exists:
            raise ValueError('Beide Speicherstaende beschaedigt: ' + self.prefix)
        return default

    def save(self, value):
        payload = json.dumps(value)
        seq = self.sequence + 1
        text = json.dumps(dict(sequence=seq, hash=digest(payload.encode()), payload=payload))
        path = self.prefix + ('.a' if seq % 2 else '.b')
        with open(path, 'w') as f:
            f.write(text)
        with open(path) as f:
            if f.read() != text:
                raise OSError('Speicherpruefung fehlgeschlagen')
        self.sequence = seq

"""Deterministic local controller, independent of networking and wall-clock changes."""
from settings import ready_channel, ready_tank

class Tank:
    def __init__(self, cfg):
        self.cfg = cfg
        self.safe = False
        self.distance = None
        self.last_ms = None
        self.good = 0
        self.reason = 'nicht_kalibriert'

    def update(self, distance, now):
        self.last_ms = now
        self.distance = distance
        t = self.cfg
        if distance is None or not 2 <= distance <= 350:
            self.safe = False; self.good = 0; self.reason = 'sensorfehler'
        elif not ready_tank(t):
            self.safe = False; self.good = 0; self.reason = 'nicht_kalibriert'
        elif distance > t['empty_cm'] + 2 or distance < t['full_cm'] - 2:
            self.safe = False; self.good = 0; self.reason = 'ausserhalb_kalibrierung'
        elif distance >= t['stop_cm']:
            self.safe = False; self.good = 0; self.reason = 'wasserreserve'
        elif not self.safe:
            self.good = self.good + 1 if distance <= t['resume_cm'] else 0
            if self.good >= 3:
                self.safe = True; self.reason = 'ok'
            else:
                self.reason = 'warte_auf_stabile_freigabe'
        else:
            self.reason = 'ok'

    def fresh(self, now):
        if self.last_ms is None or now - self.last_ms > 6000:
            self.safe = False; self.good = 0; self.reason = 'messung_veraltet'
        return self.safe

    def status(self, now=None):
        d = self.distance; t = self.cfg
        percent = None; liters = None
        if d is not None and ready_tank(t):
            percent = round(max(0,min(100,(t['empty_cm']-d)*100/(t['empty_cm']-t['full_cm']))),1)
            percentages = t.get('percent_points', [])
            if percentages:
                if d <= percentages[0][0]: percent = 100
                elif d >= percentages[-1][0]: percent = 0
                else:
                    for a,b in zip(percentages,percentages[1:]):
                        if a[0] <= d <= b[0]:
                            percent = round(a[1]+(d-a[0])*(b[1]-a[1])/(b[0]-a[0]),1); break
            pts = t.get('points', [])
            if len(pts) >= 2:
                if d <= pts[0][0]: liters = pts[0][1]
                elif d >= pts[-1][0]: liters = pts[-1][1]
                else:
                    for a,b in zip(pts,pts[1:]):
                        if a[0] <= d <= b[0]:
                            liters = a[1] + (d-a[0])*(b[1]-a[1])/(b[0]-a[0]); break
        return dict(safe=self.safe, reason=self.reason, distance_cm=d, percent=percent,
                    sample_age_ms=None if now is None or self.last_ms is None else max(0,now-self.last_ms),
                    liters=None if liters is None else round(liters,2))

class Controller:
    def __init__(self, cfg, hw, store, now=0):
        self.cfg=cfg; self.hw=hw; self.store=store; self.tank=Tank(cfg['tank'])
        self.boot=now; self.now=now; self.active=None; self.maintenance=False
        self.dirty=False; self.save_at=now; self.round_robin=0; self.events=[]
        try:
            saved=store.load({}, strict=True)
            self.state=dict(blocked=saved.get('blocked',False),
                            used=saved.get('used',{}), elapsed_ms=saved.get('elapsed_ms',0),
                            faults=saved.get('faults',{}))
            self.storage_error=False
        except Exception:
            self.state=dict(blocked=True,used={},elapsed_ms=0,faults={})
            self.storage_error=True
        self.runtime={ch['id']:dict(moisture=None, raw=None, sampled=None,
            wait_until=now+cfg['safety']['boot_pause_seconds']*1000,
            baseline=None, cycle_ml=0, doses=0, reason='startpause', pending=False)
            for ch in cfg['channels']}
        self.last_tick=now
        hw.all_off()
        self.event('boot','Startpause; Pumpen aus')

    def event(self, kind, message, cid=None):
        self.events.append(dict(t=self.now//1000,kind=kind,message=message,id=cid))
        self.events=self.events[-40:]

    def persist(self):
        try:
            self.store.save(self.state); self.dirty=False; self.save_at=self.now
            return True
        except Exception:
            self.storage_error=True; self.state['blocked']=True
            self.hw.all_off(); self.active=None
            self.event('error','Speicherfehler: Bewaesserung gesperrt')
            return False

    def channel(self, cid):
        for ch in self.cfg['channels']:
            if ch['id'] == cid: return ch
        raise ValueError('Unbekannte Kanal-ID')

    def fault(self,cid,why):
        key=str(cid)
        if self.state['faults'].get(key) != why:
            self.state['faults'][key]=why; self.dirty=True
            self.event('error',why,cid)
        if self.active and self.active['id']==cid: self.finish(why)

    def sample(self,cid,raw,now):
        ch=self.channel(cid); r=self.runtime[cid]
        r['raw']=raw; r['sampled']=now
        if raw is None or not 10 <= raw <= 4085:
            r['moisture']=None
            if ch['hardware_confirmed']: self.fault(cid,'boden_sensorfehler')
            return
        if ch.get('dry_adc') is None or ch.get('wet_adc') is None or abs(ch['dry_adc']-ch['wet_adc'])<100:
            r['moisture']=None; return
        pct=(ch['dry_adc']-raw)*100/(ch['dry_adc']-ch['wet_adc'])
        r['moisture']=round(max(0,min(100,pct)),1)
        if r['baseline'] is not None and not (self.active and self.active['id']==cid) and now >= r['wait_until']:
            if r['pending']:
                r['pending']=False
                if r['moisture']-r['baseline'] >= ch['min_rise']:
                    r['baseline']=r['moisture']; r['doses']=0
                elif r['doses']>=3:
                    self.fault(cid,'keine_feuchtezunahme')
            if r['moisture']>=ch['threshold']+ch['hysteresis']:
                r['baseline']=None; r['cycle_ml']=0; r['doses']=0

    def reason(self,ch,now,calibration=False):
        cid=ch['id']; r=self.runtime[cid]
        if self.storage_error: return 'speicherfehler'
        if self.state['blocked']: return 'global_gesperrt'
        if self.maintenance: return 'wartung'
        if now-self.boot < self.cfg['safety']['boot_pause_seconds']*1000: return 'startpause'
        if not ch['enabled']: return 'deaktiviert'
        if self.state['faults'].get(str(cid)): return self.state['faults'][str(cid)]
        if not self.tank.fresh(now): return 'tank_'+self.tank.reason
        if not ch['hardware_confirmed']: return 'hardware_nicht_bestaetigt'
        if calibration: return None
        if not ready_channel(ch): return 'nicht_kalibriert'
        if r['moisture'] is None or r['sampled'] is None or now-r['sampled']>6000: return 'boden_messung_ungueltig'
        if now<r['wait_until']: return 'einwirkzeit'
        return None

    def start(self,cid,ml,source='manual',seconds=None):
        ch=self.channel(cid); r=self.runtime[cid]; now=self.now
        if self.active: return dict(ok=False,error='pumpe_bereits_aktiv')
        calibration=source=='calibration'
        why=self.reason(ch,now,calibration)
        if why: return dict(ok=False,error=why)
        if calibration:
            if ch['auto']: return dict(ok=False,error='automatik_fuer_kalibrierung_deaktivieren')
            if type(seconds) not in (int,float) or not 0.5<=seconds<=min(5,ch['max_run_seconds']):
                return dict(ok=False,error='kalibrierung_maximal_5_sekunden')
            ml=ch['max_cycle_ml']  # Conservative reservation while flow is unknown.
        else:
            if isinstance(ml,bool) or not isinstance(ml,(int,float)) or not 1<=ml<=ch['max_cycle_ml']:
                return dict(ok=False,error='menge_ungueltig')
            seconds=ml/ch['flow_ml_s']
            if seconds>ch['max_run_seconds']: return dict(ok=False,error='laufzeitlimit')
        if r['cycle_ml']+ml>ch['max_cycle_ml']: return dict(ok=False,error='zykluslimit')
        used=self.state['used']; key=str(cid)
        if used.get(key,0)+ml>ch['max_day_ml']: return dict(ok=False,error='kanal_tageslimit')
        if sum(used.values())+ml>self.cfg['safety']['max_total_day_ml']: return dict(ok=False,error='gesamt_tageslimit')
        used[key]=used.get(key,0)+ml
        if not self.persist(): return dict(ok=False,error='speicherfehler')
        r['cycle_ml']+=ml; r['doses']+=1; r['pending']=not calibration
        if r['baseline'] is None: r['baseline']=r['moisture']
        self.active=dict(id=cid,end=now+int(seconds*1000),start=now,ml=ml,source=source)
        try:
            self.hw.on(cid)
        except Exception:
            self.finish('hardwarefehler'); self.fault(cid,'hardwarefehler')
            return dict(ok=False,error='hardwarefehler')
        self.event('water','Start: %s ml reserviert (%s)' % (ml,source),cid)
        return dict(ok=True,id=cid,ml_reserved=ml,seconds=round(seconds,2))

    def finish(self,reason='fertig'):
        if not self.active: return
        job=self.active; self.hw.all_off(); self.active=None
        self.runtime[job['id']]['wait_until']=self.now+self.channel(job['id'])['soak_seconds']*1000
        if job['source']=='calibration':
            r=self.runtime[job['id']]; r['baseline']=None; r['cycle_ml']=0; r['doses']=0; r['pending']=False
        self.event('water','Stopp: '+reason,job['id'])

    def stop(self):
        self.hw.all_off(); self.finish('globaler_stopp')
        self.state['blocked']=True; self.dirty=True; self.persist()
        self.event('stop','Alle Pumpen und Automatik gesperrt')
        return dict(ok=True)

    def release(self,cid=None):
        if self.active: return dict(ok=False,error='pumpe_aktiv')
        if self.storage_error: return dict(ok=False,error='speicherfehler')
        if cid is None: self.state['blocked']=False
        else:
            self.channel(cid); self.state['faults'].pop(str(cid),None)
            r=self.runtime[cid]; r['baseline']=None; r['cycle_ml']=0; r['doses']=0; r['pending']=False
        self.dirty=True
        return dict(ok=self.persist())

    def tick(self,now,allow_auto=True):
        elapsed=max(0,now-self.last_tick); self.last_tick=now; self.now=now
        self.state['elapsed_ms']+=elapsed
        if self.active:
            job=self.active
            r=self.runtime[job['id']]
            if now>=job['end']: self.finish()
            elif not self.tank.fresh(now): self.finish('tank_'+self.tank.reason)
            elif r['sampled'] is None or now-r['sampled']>6000 or r['raw'] is None:
                self.finish('boden_messung_veraltet')
        if self.active: return
        if self.state['elapsed_ms']>=86400000:
            self.state['elapsed_ms']=0; self.state['used']={}; self.dirty=True
            self.event('budget','Neues 24-Stunden-Budget')
        if self.dirty or now-self.save_at>=600000:
            if not self.persist(): return
        if not allow_auto: return
        chs=self.cfg['channels']
        for offset in range(len(chs)):
            idx=(self.round_robin+offset)%len(chs); ch=chs[idx]; r=self.runtime[ch['id']]
            why=self.reason(ch,now)
            if not why and not ch['auto']: why='automatik_aus'
            if not why and r['moisture']>=ch['threshold'] and r['baseline'] is None: why='feucht_genug'
            if not why and r['moisture']>=ch['threshold']+ch['hysteresis']: why='feucht_genug'
            r['reason']=why or 'trocken'
            if not why:
                res=self.start(ch['id'],ch['portion_ml'],'auto')
                if res['ok']:
                    self.round_robin=(idx+1)%len(chs); break
                r['reason']=res['error']
                if res['error']=='zykluslimit': self.fault(ch['id'],'zykluslimit_erreicht')

    def status(self):
        return dict(blocked=self.state['blocked'],storage_error=self.storage_error,
            active=self.active,tank=self.tank.status(self.now),used_total_ml=sum(self.state['used'].values()),
            budget_hours_remaining=round((86400000-self.state['elapsed_ms'])/3600000,2),
            channels=[dict(id=ch['id'],name=ch['name'],auto=ch['auto'],
                moisture=self.runtime[ch['id']]['moisture'],raw=self.runtime[ch['id']]['raw'],
                reason=self.runtime[ch['id']]['reason'],fault=self.state['faults'].get(str(ch['id'])),
                wait_seconds=max(0,(self.runtime[ch['id']]['wait_until']-self.now)//1000),
                used_ml=self.state['used'].get(str(ch['id']),0)) for ch in self.cfg['channels']],
            events=self.events)

"""ESP32-specific I/O. HC-SR04 echo MUST be level-shifted to 3.3 V."""
import time
from machine import Pin, ADC, time_pulse_us

class Hardware:
    def __init__(self,cfg):
        self.pumps={}; self.sensors={}; self.low={}; self.trig=None; self.echo=None
        try:
            for ch in cfg['channels']:
                cid=ch['id']
                if ch['hardware_confirmed']:
                    low=ch['active_low']; self.low[cid]=low
                    self.pumps[cid]=Pin(ch['pump_pin'],Pin.OUT,value=1 if low else 0)
                if ch['sensor_pin'] is not None and cfg['board']!='unknown':
                    adc=ADC(Pin(ch['sensor_pin']))
                    adc.atten(ADC.ATTN_11DB)
                    try: adc.width(ADC.WIDTH_12BIT)
                    except AttributeError: pass
                    self.sensors[cid]=adc
            t=cfg['tank']
            if cfg['board']!='unknown' and t['trigger_pin'] is not None and t['echo_pin'] is not None:
                self.trig=Pin(t['trigger_pin'],Pin.OUT,value=0)
                self.echo=Pin(t['echo_pin'],Pin.IN)
        except Exception:
            self.all_off()
            raise

    def all_off(self):
        for cid,p in self.pumps.items(): p.value(1 if self.low[cid] else 0)

    def on(self,cid):
        self.all_off()  # physical interlock as well as controller interlock
        if cid not in self.pumps: raise ValueError('Pumpenhardware nicht freigegeben')
        self.pumps[cid].value(0 if self.low[cid] else 1)

    def raw(self,cid):
        if cid not in self.sensors: return None
        try:
            vals=[self.sensors[cid].read() for _ in range(5)]; vals.sort()
            return vals[2]
        except Exception:
            return None

    def distance(self):
        if self.trig is None: return None
        self.trig.value(0); time.sleep_us(2)
        self.trig.value(1); time.sleep_us(10); self.trig.value(0)
        try:
            duration=time_pulse_us(self.echo,1,22000)
            if duration<=0: return None
            d=duration*0.0343/2
            return round(d,2) if 2<=d<=350 else None
        except Exception:
            return None

"""Local sensing and control run independently of Wi-Fi/MQTT availability."""
import time
import gc
import json
import machine
import network
import os
try: import asyncio
except ImportError: import uasyncio as asyncio
from settings import defaults,validate,clone,VERSION
from persistence import Store
from hardware_v4 import Hardware
from controller import Controller
from web_v4 import Web
from mqtt_v4 import MQTT
from updater import Updater

class Clock:
    def __init__(self): self.previous=time.ticks_ms(); self.ms=0
    def now(self):
        current=time.ticks_ms(); self.ms+=max(0,time.ticks_diff(current,self.previous)); self.previous=current
        return self.ms

class Application:
    def __init__(self,root,code):
        self.root=root; self.code=code; self.clock=Clock()
        self.config_store=Store(root+'/config')
        self.config_error=''
        try: self.cfg=validate(self.config_store.load(defaults(),strict=True))
        except Exception as exc:
            self.cfg=defaults(); self.config_error=str(exc)
        self.hw=Hardware(self.cfg)
        self.controller=Controller(self.cfg,self.hw,Store(root+'/state'))
        if self.config_error:
            self.controller.state['blocked']=True
            self.controller.event('error','Konfiguration ungueltig: neu einrichten')
        self.wlan=network.WLAN(network.STA_IF); self.ap=network.WLAN(network.AP_IF)
        self.control_healthy=False; self.network_recovery_requested=False
        self.history=[]; self.web=Web(self); self.updater=Updater(root,self.controller)
        import binascii
        self.uid=binascii.hexlify(machine.unique_id()).decode()
        self.mqtt=MQTT(self,self.uid)

    def status(self):
        data=self.controller.status()
        data.update(version=VERSION,uptime_seconds=self.clock.now()//1000,
                    heap=gc.mem_free(),mqtt=dict(connected=self.mqtt.connected,error=self.mqtt.error),
                    config_error=self.config_error)
        return data

    def action(self,data):
        action=data.get('action'); cid=data.get('id')
        if cid is not None and type(cid) is not int: raise ValueError('Kanal-ID muss eine Zahl sein')
        self.controller.tick(self.clock.now(),allow_auto=False)
        if action=='stop': return self.controller.stop()
        if action=='release': return self.controller.release()
        if action=='clear':
            if cid is None: raise ValueError('Kanal-ID fehlt')
            return self.controller.release(cid)
        if action=='run':
            if cid is None: raise ValueError('Kanal-ID fehlt')
            return self.controller.start(cid,data.get('ml'))
        if action=='calibrate':
            if cid is None: raise ValueError('Kanal-ID fehlt')
            return self.controller.start(cid,None,'calibration',data.get('seconds'))
        if action=='auto':
            if self.controller.active or self.controller.maintenance: return dict(ok=False,error='pumpe_aktiv_oder_wartung')
            enabled=data.get('enabled')
            if type(enabled) is not bool: raise ValueError('enabled muss bool sein')
            self.controller.channel(cid)
            candidate=clone(self.cfg)
            for ch in candidate['channels']:
                if ch['id']==cid: ch['auto']=enabled
            validate(candidate); self.config_store.save(candidate)
            self.controller.channel(cid)['auto']=enabled
            return dict(ok=True)
        if action=='reboot':
            self.controller.stop(); return dict(ok=True,reboot=True)
        raise ValueError('Aktion unbekannt')

    async def reboot(self):
        self.hw.all_off(); self.controller.maintenance=True
        await asyncio.sleep(1); machine.reset()

    async def control(self):
        sensor_due=0; tank_due=0; history_due=0
        watchdog=machine.WDT(timeout=8000)
        while True:
            now=self.clock.now(); self.controller.tick(now)
            if now>=sensor_due:
                for ch in self.cfg['channels']:
                    self.controller.sample(ch['id'],self.hw.raw(ch['id']),now)
                sensor_due=now+2000
            if now>=tank_due:
                # A single timeout is bounded to 22 ms per pulse phase. Never filter away a low tank.
                distance=self.hw.distance()
                previous=self.controller.tank.reason
                self.controller.tank.update(distance,self.clock.now())
                current=self.controller.tank.reason
                if current!=previous:
                    self.controller.event('info' if self.controller.tank.safe else 'error','Tank: '+current)
                tank_due=now+2000
            self.controller.tick(self.clock.now())
            if now>=history_due:
                self.history.append(dict(t=now//1000,values=[self.controller.runtime[c['id']]['moisture'] for c in self.cfg['channels']]))
                self.history=self.history[-288:] # 5-minute samples, 24 hours, bounded RAM
                history_due=now+300000
            self.control_healthy=True
            watchdog.feed()
            await asyncio.sleep_ms(20)

    def setup_ap(self):
        self.ap.active(True)
        password=self.cfg['wifi']['ap_password']
        if password:
            self.ap.config(essid='Irrigation-'+self.uid[-6:],password=password,authmode=3)
        else:
            self.ap.config(essid='Irrigation-'+self.uid[-6:],authmode=0)
        print('Setup-WLAN:',self.ap.ifconfig()[0])

    async def wifi(self):
        self.wlan.active(True)
        try: self.wlan.config(pm=network.WLAN.PM_NONE)
        except (AttributeError,ValueError): pass
        attempted=-30000
        while True:
            now=self.clock.now()
            if self.network_recovery_requested and not self.controller.active:
                self.network_recovery_requested=False
                previous_maintenance=self.controller.maintenance
                self.controller.maintenance=True
                self.web.server.close()
                self.wlan.disconnect(); self.wlan.active(False)
                await asyncio.sleep_ms(500)
                self.wlan.active(True)
                try: self.wlan.config(pm=network.WLAN.PM_NONE)
                except (AttributeError,ValueError): pass
                await self.web.start()
                self.controller.maintenance=previous_maintenance
                attempted=now-30000
                print('WLAN_RECOVERY: restarted idle network after MQTT failures')
            if self.wlan.isconnected():
                if self.ap.active(): self.ap.active(False)
            elif not self.controller.active and now-attempted>=30000:
                attempted=now
                if self.cfg['wifi']['ssid']:
                    try: self.wlan.connect(self.cfg['wifi']['ssid'],self.cfg['wifi']['password'])
                    except Exception: pass
                if not self.ap.active(): self.setup_ap()
            await asyncio.sleep(2)

    async def run(self):
        self.setup_ap()
        await self.web.start()
        # A pending update is healthy only after the control task has run without an exception.
        tasks=[asyncio.create_task(self.control()),asyncio.create_task(self.wifi()),asyncio.create_task(self.mqtt.run())]
        await asyncio.sleep(3)
        if not self.control_healthy: raise RuntimeError('Steuerung nicht gestartet')
        release=Store(self.root+'/release'); rec=release.load(None,strict=True)
        if rec and rec.get('pending'):
            rec['pending']=False; rec['attempted']=False; release.save(rec)
        await asyncio.gather(*tasks)

async def main(root,code):
    app=None
    try:
        app=Application(root,code)
        await app.run()
    finally:
        if app: app.hw.all_off()

"""Bounded asynchronous HTTP requests; slow clients cannot hold the control loop."""

import json

try: import asyncio

except ImportError: import uasyncio as asyncio

from settings import validate

STATIC_FILES={'/': ('index.html', 'text/html; charset=utf-8', 'no-cache', '287ea1cc2e1ce32d'), '/ui.5488754f1f67.css': ('ui.5488754f1f67.css', 'text/css; charset=utf-8', 'public, max-age=31536000, immutable', '5488754f1f671d00'), '/ui.1959ae6e4ef8.js': ('ui.1959ae6e4ef8.js', 'text/javascript; charset=utf-8', 'public, max-age=31536000, immutable', '1959ae6e4ef8eb3f')}

class Web:

    def __init__(self,app):

        self.app=app; self.clients=0; self.server=None

    async def start(self,port=80):

        self.server=await asyncio.start_server(self.handle,'0.0.0.0',port,backlog=3)

    async def send(self,w,data,status=200,ctype='application/json'):

        if not isinstance(data,bytes):

            data=(json.dumps(data,separators=(',',':')) if ctype=='application/json' else data).encode()

        w.write(('HTTP/1.1 %d OK\r\nContent-Type: %s\r\nContent-Length: %d\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n\r\n' % (status,ctype,len(data))).encode())

        await asyncio.wait_for_ms(w.drain(),2000)

        for i in range(0,len(data),1024):

            w.write(data[i:i+1024]); await asyncio.wait_for_ms(w.drain(),2000)

    async def send_static(self,w,info,headers,head_only=False):
        import os
        name,ctype,cache,digest=info
        accepted=headers.get('accept-encoding','').split(',')
        compressed=any(p.strip().split(';')[0]=='gzip' and not any(q.strip() in ('q=0','q=0.0','q=0.00','q=0.000') for q in p.split(';')[1:]) for p in accepted)
        path=self.app.code+'/'+name+('.gz' if compressed else '')
        tag='"'+digest+('-gz' if compressed else '')+'"'
        common='ETag: %s\r\nCache-Control: %s\r\nVary: Accept-Encoding\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n'%(tag,cache)
        if tag in [t.strip() for t in headers.get('if-none-match','').split(',')]:
            w.write(('HTTP/1.1 304 Not Modified\r\n'+common+'\r\n').encode())
            await asyncio.wait_for_ms(w.drain(),2000)
            return
        size=os.stat(path)[6]
        extra='Content-Encoding: gzip\r\n' if compressed else ''
        w.write(('HTTP/1.1 200 OK\r\nContent-Type: %s\r\nContent-Length: %d\r\n'%(ctype,size)+extra+common+'\r\n').encode())
        await asyncio.wait_for_ms(w.drain(),2000)
        if head_only:return
        buffer=bytearray(1024);view=memoryview(buffer)
        with open(path,'rb') as f:
            while True:
                count=f.readinto(buffer)
                if not count:break
                w.write(view[:count])
                await asyncio.wait_for_ms(w.drain(),2000)

    async def read(self,r,length):

        body=b''

        while len(body)<length:

            chunk=await asyncio.wait_for_ms(r.read(min(512,length-len(body))),2000)

            if not chunk: raise ValueError('Anfrage unvollstaendig')

            body+=chunk

        return body

    async def line(self,r,limit):

        result=b''

        while len(result)<=limit:

            byte=await r.read(1) # Caller bounds the whole line; avoid one timer task per byte.

            if not byte: raise ValueError('Header unvollstaendig')

            result+=byte

            if byte==b'\n': return result

        raise ValueError('Header zu lang')

    async def handle(self,r,w):

        if self.clients>=3:

            w.close(); return

        self.clients+=1

        try:

            first=await asyncio.wait_for_ms(self.line(r,256),3000)

            if len(first)>256: raise ValueError('URL zu lang')

            method,path,_=first.decode().strip().split()

            headers={}; total=0

            while True:

                line=await asyncio.wait_for_ms(self.line(r,512),3000); total+=len(line)

                if total>2048 or len(line)>512: raise ValueError('Header zu gross')

                if line==b'\r\n': break

                if not line: raise ValueError('Header unvollstaendig')

                key,value=line.decode().split(':',1); headers[key.lower()]=value.strip()

            length=int(headers.get('content-length','0'))

            if length<0 or 'transfer-encoding' in headers: raise ValueError('Transferformat ungueltig')

            clean=path.split('?',1)[0]

            if method=='POST':

                # No CORS and a required non-simple header block cross-origin browser writes.

                if headers.get('x-irrigation')!='local':

                    await self.send(w,dict(ok=False,error='Anfrage nicht erlaubt'),403); return

                origin=headers.get('origin')

                if origin and origin!='http://'+headers.get('host',''):

                    await self.send(w,dict(ok=False,error='Fremder Ursprung'),403); return

            if method in ('GET','HEAD') and clean in STATIC_FILES:
                await self.send_static(w,STATIC_FILES[clean],headers,method=='HEAD')
                return

            if method=='GET':

                if clean=='/api/status': result=self.app.status()

                elif clean=='/api/config': result=self.app.cfg

                elif clean=='/api/history': result=self.app.history
                elif clean=='/api/history-view':
                    result=dict(history=self.app.history,events=self.app.controller.events)
                elif clean=='/api/overview':
                    result=self.app.status()
                    result['events']=result['events'][-5:]
                    if path.split('?',1)[-1]=='config=1':
                        result['ui']=dict(safety=dict(max_total_day_ml=self.app.cfg['safety']['max_total_day_ml']),
                            channels=[dict(id=c['id'],name=c['name'],threshold=c['threshold'],
                                portion_ml=c['portion_ml'],max_day_ml=c['max_day_ml']) for c in self.app.cfg['channels']])

                else:

                    await self.send(w,dict(ok=False,error='Nicht gefunden'),404); return

                await self.send(w,result); return

            if method!='POST':

                await self.send(w,dict(ok=False,error='Methode ungueltig'),405); return

            if clean=='/api/update/file':

                if '?name=' not in path: raise ValueError('Dateiname fehlt')

                name=path.split('?name=',1)[1]

                target=self.app.updater.target(name,length)

                self.app.updater.uploading=True

                try:

                    with open(target,'wb') as f:

                        remaining=length

                        while remaining:

                            chunk=await asyncio.wait_for_ms(r.read(min(512,remaining)),3000)

                            if not chunk: raise ValueError('Upload unvollstaendig')

                            f.write(chunk); remaining-=len(chunk)

                    self.app.updater.verify_file(name)

                finally:

                    self.app.updater.uploading=False

                await self.send(w,dict(ok=True)); return

            if length>12000: raise ValueError('Anfrage zu gross')

            body=await self.read(r,length)

            data=json.loads(body.decode()) if body else {}

            if not isinstance(data,dict): raise ValueError('JSON-Objekt erforderlich')

            if clean=='/api/config':

                validate(data)

                if self.app.controller.active: raise ValueError('Pumpe zuerst stoppen')

                self.app.controller.maintenance=True

                self.app.config_store.save(data)

                result=dict(ok=True,reboot=True)

            elif clean=='/api/action': result=self.app.action(data)

            elif clean=='/api/update/begin': result=self.app.updater.begin(data)

            elif clean=='/api/update/commit': result=self.app.updater.commit()

            else:

                await self.send(w,dict(ok=False,error='Nicht gefunden'),404); return

            await self.send(w,result,200 if result.get('ok') else 409)

            if result.get('reboot'): asyncio.create_task(self.app.reboot())

        except (ValueError,KeyError,TypeError) as exc:

            try: await self.send(w,dict(ok=False,error=str(exc)),400)

            except Exception: pass

        except Exception:

            try: await self.send(w,dict(ok=False,error='Verbindung oder Speicher fehlgeschlagen'),500)

            except Exception: pass

        finally:

            self.clients-=1

            w.close()

            try: await asyncio.wait_for_ms(w.wait_closed(),500)

            except Exception: pass

"""Verified staged releases. The stable bootstrap handles failed-start rollback."""
import os
import json
from persistence import digest
from web_v4 import STATIC_FILES

CORE_FILES=('settings.py','persistence.py','controller.py','hardware_v4.py','runtime.py',
            'web_v4.py','mqtt_v4.py','updater.py','index.html')
FILES=CORE_FILES+tuple(name for info in STATIC_FILES.values()
    for name in (info[0],info[0]+'.gz') if name not in CORE_FILES)

class Updater:
    def __init__(self,root,controller):
        self.root=root; self.controller=controller; self.manifest=None; self.stage=None
        self.uploading=False

    def begin(self,manifest):
        if self.uploading: raise ValueError('Upload bereits aktiv')
        self.controller.stop(); self.controller.maintenance=True
        version=manifest.get('version','')
        if not isinstance(version,str) or not version or len(version)>24 or any(c not in '0123456789.-abcdefghijklmnopqrstuvwxyz' for c in version):
            raise ValueError('Version ungueltig')
        files=manifest.get('files',[])
        if not isinstance(files,list) or any(not isinstance(f,dict) for f in files):
            raise ValueError('Manifest ungueltig')
        names=[f.get('name') for f in files]
        if any(not isinstance(n,str) for n in names):raise ValueError('Manifest ungueltig')
        extras=set(names)-set(CORE_FILES)
        plain=[n for n in extras if n.endswith(('.js','.css'))]
        valid_names=all(len(n.split('.'))==3 and n.split('.')[0]=='ui'
            and len(n.split('.')[1])==12 and all(c in '0123456789abcdef' for c in n.split('.')[1])
            for n in plain)
        expected=set(plain+[n+'.gz' for n in plain]+['index.html.gz'])
        if (len(files)!=len(FILES) or len(set(names))!=len(names) or not set(CORE_FILES)<=set(names)
            or len(plain)!=2 or not any(n.endswith('.js') for n in plain)
            or not any(n.endswith('.css') for n in plain) or not valid_names or extras!=expected):
            raise ValueError('Vollstaendiges Updatepaket erforderlich')
        total=0
        for f in files:
            size=f.get('size'); sha=f.get('sha256','')
            if type(size) is not int or not 1<=size<=48000 or len(sha)!=64 or any(c not in '0123456789abcdef' for c in sha):
                raise ValueError('Manifest ungueltig')
            total+=size
        if total>200000: raise ValueError('Updatepaket zu gross')
        self.stage=self.root+'/releases/update-'+str(self.controller.now)
        os.mkdir(self.stage)
        self.manifest=manifest
        return dict(ok=True)

    def target(self,name,size):
        if self.uploading: raise ValueError('Upload bereits aktiv')
        if self.manifest is None: raise ValueError('Update zuerst beginnen')
        match=[f for f in self.manifest['files'] if f['name']==name]
        if len(match)!=1 or match[0]['size']!=size: raise ValueError('Datei passt nicht zum Manifest')
        return self.stage+'/'+name

    def verify_file(self,name):
        info=[f for f in self.manifest['files'] if f['name']==name][0]
        path=self.stage+'/'+name
        import hashlib
        import binascii
        h=hashlib.sha256()
        with open(path,'rb') as f:
            while True:
                chunk=f.read(512)
                if not chunk: break
                h.update(chunk)
        if os.stat(path)[6]!=info['size'] or binascii.hexlify(h.digest()).decode()!=info['sha256']:
            raise ValueError('Dateipruefung fehlgeschlagen: '+name)

    def commit(self):
        if self.uploading or self.manifest is None: raise ValueError('Update unvollstaendig')
        for f in self.manifest['files']: self.verify_file(f['name'])
        from persistence import Store
        store=Store(self.root+'/release')
        current=store.load({'active':'factory','previous':None,'pending':False})
        store.save(dict(active=self.stage.rsplit('/',1)[-1],previous=current['active'],pending=True,attempted=False))
        self.manifest=None
        return dict(ok=True,reboot=True)

